(8, 'rtee', '1', '{\"version\":\"7.3.1\",\"objects\":[{\"fontSize\":14,\"fontWeight\":\"normal\",\"fontFamily\":\"Times New Roman\",\"fontStyle\":\"normal\",\"lineHeight\":1.16,\"text\":\"Si eres un profesional de la carrera de guía {{nombres}} oficial de turismo y cuentas con una certificación en actividades especializadas de guiado, debes solicitar una acreditación al órgano competente para ejercer dichas actividades. Si estás en Lima, debes hacerlo en el Ministerio de Comercio Exterior y Turismo (Mincetur), y si estás en otro departamento, en el gobierno regional correspondiente.\",\"charSpacing\":0,\"textAlign\":\"left\",\"styles\":[{\"start\":45,\"end\":56,\"style\":{\"fontSize\":20,\"fontWeight\":\"normal\",\"fontFamily\":\"Times New Roman\",\"fontStyle\":\"normal\",\"underline\":false,\"overline\":false,\"linethrough\":false,\"stroke\":null,\"strokeWidth\":1,\"fill\":\"#000\",\"deltaY\":0,\"textBackgroundColor\":\"\",\"textDecorationThickness\":66.667}}],\"pathStartOffset\":0,\"pathSide\":\"left\",\"pathAlign\":\"baseline\",\"underline\":false,\"overline\":false,\"linethrough\":false,\"textBackgroundColor\":\"\",\"direction\":\"ltr\",\"textDecorationThickness\":66.667,\"minWidth\":20,\"splitByGrapheme\":false,\"type\":\"Textbox\",\"version\":\"7.3.1\",\"originX\":\"center\",\"originY\":\"center\",\"left\":563.5132,\"top\":279.4385,\"width\":577.5313,\"height\":97.0896,\"fill\":\"#000\",\"stroke\":null,\"strokeWidth\":1,\"strokeDashArray\":null,\"strokeLineCap\":\"butt\",\"strokeDashOffset\":0,\"strokeLineJoin\":\"miter\",\"strokeUniform\":false,\"strokeMiterLimit\":4,\"scaleX\":1.6824,\"scaleY\":1.6824,\"angle\":0,\"flipX\":false,\"flipY\":false,\"opacity\":1,\"shadow\":null,\"visible\":true,\"backgroundColor\":\"\",\"fillRule\":\"nonzero\",\"paintFirst\":\"fill\",\"globalCompositeOperation\":\"source-over\",\"skewX\":0,\"skewY\":0},{\"fontSize\":20,\"fontWeight\":\"normal\",\"fontFamily\":\"Times New Roman\",\"fontStyle\":\"normal\",\"lineHeight\":1.16,\"tex