--
-- Volcado de datos para la tabla `vistas`
--

INSERT INTO `vistas` (`id`, `nombre`, `ruta`, `icono`, `descripcion`, `precio`) VALUES
(1, 'Produccion', '/Principal', 'pi pi-th-large', 'Modulo principal para gestionar y supervisar los procesos de produccion, controlando tareas, estados, tiempos y flujo operativo de la empresa.', 19),
(2, 'Productos', '/Principal/Page/Productos', 'pi pi-box', 'Permite registrar, editar y administrar los productos de la empresa, incluyendo precios, categorias, stock e informacion comercial.', 19),
(3, 'Almacen', '/Principal/Page/Almacen', 'pi pi-warehouse', 'Gestiona el inventario y movimiento de productos dentro del almacen, controlando entradas, salidas y disponibilidad de stock.', 19),
(4, 'Interfaz de Venta', '/Principal/Page/Ventas', 'pi pi-shopping-cart', 'Sistema de ventas rapido e intuitivo para registrar pedidos, emitir comprobantes y realizar operaciones comerciales en tiempo real.', 19),
(5, 'Preventas', '/Principal/Page/Pedidos', 'pi pi-send', 'Permite registrar pedidos anticipados y cotizaciones antes de concretar una venta oficial, optimizando el seguimiento comercial.', 19),
(6, 'Gestion Envios', '/Principal/Page/GestionEnvios', 'pi pi-truck', 'Administra el proceso de envio y distribucion de pedidos, permitiendo controlar rutas, estados y entregas.', 19),
(7, 'Gestión de Roles', '/Principal/Page/GestionRoles', 'pi pi-briefcase', 'Modulo de seguridad para administrar roles, permisos y accesos de usuarios dentro del sistema.', 19),
(8, 'Personales', '/Principal/Page/Personal', 'pi pi-users', 'Gestiona la informacion del personal de la empresa, incluyendo datos laborales, cargos y registros administrativos.', 19),
(9, 'Confirmacion', '/Principal/Page/ConfirmacionPedido', 'pi pi-clipboard', 'Permite validar y confirmar pedidos realizados por clientes antes de su procesamiento o despacho.', 19),
(10, 'Asistencia', '/Principal/Page/Asistencia', 'pi pi-address-book', 'Control de asistencia del personal mediante registros de ingreso, salida, horarios y reportes.', 19),
(11, 'Talleres', '/Principal/Page/Talleres', 'pi pi-shop', 'Administra talleres, areas de trabajo o sucursales relacionadas con la produccion y operacion de la empresa.', 19),
(12, 'Clientes', '/Principal/Page/Cliente', 'pi pi-users', 'Permite registrar y gestionar informacion de clientes, historial de compras, contactos y seguimiento comercial.', 19),
(13, 'Documentos', '/Principal/Page/Documentos', 'pi pi-book', 'Gestion documental para almacenar, organizar y consultar archivos importantes del sistema y la empresa.', 19),
(14, 'Pagina Web', '/Principal/Page/Pagina-web', 'pi pi-desktop', 'Modulo para administrar configuraciones, contenido y herramientas relacionadas con la pagina web de la empresa.', 19),
(15, 'Dashboard', '/Principal/Page/Dashboard', 'pi pi-chart-bar', 'Dashboard principal para visualizar métricas, estadísticas y resumen general del sistema en tiempo real.', 56),
(16, 'Administracion', '/Principal/Page/Administracion', 'pi pi-truck', 'Administra tus finanzas de forma sencilla. Registra ingresos, gastos y préstamos, y visualiza toda la información mediante gráficos y estadísticas en tiempo real para tomar mejores decisiones financieras.', 20),
(17, 'WorkSpace', '/Principal/Page/Workspace', 'pi pi-box', 'Espacio de trabajo', 20),
(18, 'Admin Workpace', '/Principal/Page/AdminWorkspace', 'pi pi-box', 'Espacio de trabajo (Administrador)', 45),
(19, 'Admin Eventos', '/Principal/Page/AdminEventos', 'pi pi-box', 'Espacio de Creacion de eventos(Administrador)', 100);

